            public void Print(StructuredStringBuilder sb, Weapon.Mask<bool>? printMask = null)
            {
                sb.AppendLine($"{nameof(Weapon.Mask<TItem>)} =>");
                using (sb.Brace())
                {
                    if (printMask?.VirtualMachineAdapter?.Overall ?? true)
                    {
                        VirtualMachineAdapter?.Print(sb);
                    }
                    if (printMask?.ObjectBounds?.Overall ?? true)
                    {
                        ObjectBounds?.Print(sb);
                    }
                    if (printMask?.PreviewTransform ?? true)
                    {
                        sb.AppendItem(PreviewTransform, "PreviewTransform");
                    }
                    if (printMask?.AnimationSound ?? true)
                    {
                        sb.AppendItem(AnimationSound, "AnimationSound");
                    }
                    if (printMask?.SnapshotTemplate ?? true)
                    {
                        sb.AppendItem(SnapshotTemplate, "SnapshotTemplate");
                    }
                    if (printMask?.PHST ?? true)
                    {
                        sb.AppendItem(PHST, "PHST");
                    }
                    if (printMask?.XALG ?? true)
                    {
                        sb.AppendItem(XALG, "XALG");
                    }
                    if ((printMask?.ObjectPlacementDefaults?.Overall ?? true)
                        && ObjectPlacementDefaults is {} ObjectPlacementDefaultsItem)
                    {
                        sb.AppendLine("ObjectPlacementDefaults =>");
                        using (sb.Brace())
                        {
                            sb.AppendItem(ObjectPlacementDefaultsItem.Overall);
                            if (ObjectPlacementDefaultsItem.Specific != null)
                            {
                                foreach (var subItem in ObjectPlacementDefaultsItem.Specific)
                                {
                                    using (sb.Brace())
                                    {
                                        subItem?.Print(sb);
                                    }
                                }
                            }
                        }
                    }
                    if (printMask?.Name ?? true)
                    {
                        sb.AppendItem(Name, "Name");
                    }
                    if (printMask?.Model?.Overall ?? true)
                    {
